SELECT     im.ITEM                                         AS item_number,     im.ITEM_DESC                                    AS item_description,     im.DEPT                                         AS department,     d.DEPT_NAME                                     AS department_name,     ril.LOCATION                                    AS location,     COALESCE(st.STORE_NAME, wh.WH_NAME)             AS location_name,     ril.LOC_TYPE                                    AS location_type,     ril.REPL_METHOD                                 AS replenishment_method,     ril.STATUS                                      AS replenishment_status,     ril.PRIMARY_REPL_SUPPLIER                       AS primary_repl_supplier,      oh.ORDER_NO                                     AS order_number,     oh.ORDER_TYPE                                   AS order_type,     oh.STATUS                                       AS po_status,     oh.WRITTEN_DATE                                 AS po_written_date,     oh.NOT_BEFORE_DATE                              AS not_before_date,     oh.NOT_AFTER_DATE                               AS not_after_date,     oh.ORIG_APPROVAL_DATE                           AS approval_date,     oh.SUPPLIER                                     AS supplier_number,     su.SUP_NAME                                     AS supplier_name,      ol.QTY_ORDERED                                  AS qty_ordered,     ol.QTY_RECEIVED                                 AS qty_received,     ol.QTY_CANCELLED                                AS qty_cancelled,     ol.UNIT_COST                                    AS unit_cost,     ol.UNIT_RETAIL                                  AS unit_retail,     ol.ESTIMATED_INSTOCK_DATE                       AS estimated_instock_date,      CASE         WHEN TRUNC(oh.NOT_AFTER_DATE) &lt; TRUNC(SYSDATE)             THEN 'LATE'         WHEN TRUNC(oh.NOT_AFTER_DATE) BETWEEN TRUNC(SYSDATE)             AND TRUNC(SYSDATE) + 7             THEN 'DUE IN 7 DAYS'     END                                             AS po_urgency_flag,      TRUNC(oh.NOT_AFTER_DATE) - TRUNC(SYSDATE)       AS days_to_not_after_date,     TRUNC(SYSDATE) - TRUNC(oh.WRITTEN_DATE)         AS days_since_order  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC                  ril      JOIN MFCS_RDS.RDS_WV_ITEM_MASTER                im         ON  im.ITEM             = ril.ITEM      LEFT JOIN MFCS_RDS.RDS_WV_DEPS                  d         ON  d.DEPT              = im.DEPT      JOIN MFCS_RDS.RDS_WV_ORDLOC                     ol         ON  ol.ITEM             = ril.ITEM         AND ol.LOCATION         = ril.LOCATION      JOIN MFCS_RDS.RDS_WV_ORDHEAD                    oh         ON  oh.ORDER_NO         = ol.ORDER_NO      JOIN MFCS_RDS.RDS_WV_SUPS                       su         ON  su.SUPPLIER         = oh.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE                 st         ON  st.STORE            = ril.LOCATION         AND ril.LOC_TYPE        = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_WH                    wh         ON  wh.WH               = ril.LOCATION         AND ril.LOC_TYPE        = 'W'  WHERE     ril.STATUS                  = 'A'      AND oh.ORDER_TYPE           IN ('ARB', 'BRB')      AND oh.STATUS               IN ('A', 'S')      AND NVL(ol.QTY_RECEIVED, 0) &lt; ol.QTY_ORDERED      AND (             TRUNC(oh.NOT_AFTER_DATE) &lt; TRUNC(SYSDATE)              OR TRUNC(oh.NOT_AFTER_DATE) BETWEEN TRUNC(SYSDATE)                 AND TRUNC(SYSDATE) + 7         )  ORDER BY     po_urgency_flag             ASC,     days_to_not_after_date      ASC,     ril.LOCATION,     im.DEPT,     ril.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>ITEM_NUMBER</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM_DESCRIPTION</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPARTMENT</ds:na